(()=>{const out={},ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');document.body.append(svg);for(const text of ['ABC','😀','A😀B','fi','é','  A  B  ','']){const n=document.createElementNS(ns,'text');n.style.fontFamily='Arial';n.style.fontSize='16px';n.setAttribute('x','10');n.setAttribute('y','20');n.textContent=text;svg.append(n);const round=v=>Math.round(v*1e5)/1e5,rows=[];for(let i=0;i<n.getNumberOfChars();i++){const s=n.getStartPositionOfChar(i),e=n.getEndPositionOfChar(i),b=n.getExtentOfChar(i);rows.push([round(s.x),round(s.y),round(e.x),round(e.y),...[b.x,b.y,b.width,b.height].map(round),n.getRotationOfChar(i),round(n.getSubStringLength(i,1))])}out[text]={count:n.getNumberOfChars(),rows,hit:n.getCharNumAtPosition({x:12,y:15})};for(const index of [-1,999,NaN])try{n.getExtentOfChar(index);out[text]['bad'+index]='ok'}catch(e){out[text]['bad'+index]=e.name}n.remove()}svg.remove();return out})()